insert into sign_notes(request_id,note_type,note_text,sent_to_applicant,created_by,created_at) values ('5a1e0001-0000-4000-8000-000000000003','general','בקשה חדשה. חסרה תכנית התארגנות A3, וחסרים שמות מנהל העבודה ואחראי הבטיחות. ממתינה לבדיקה ראשונה.',false,'צוות העירייה',now()-interval '20 hours');